function initSmoothScrolling(){document.querySelectorAll('a[href^="#"]').forEach(t=>{t.addEventListener("click",function(t){const e=this.getAttribute("href");if("#"===e)return;const n=document.querySelector(e);if(n){t.preventDefault();const e=80,o=n.getBoundingClientRect().top+window.pageYOffset-e;window.scrollTo({top:o,behavior:"smooth"})}})})}function initMobileMenu(){const t=document.querySelector(".mobile-menu-toggle"),e=document.querySelector(".nav-menu");t&&e&&(t.addEventListener("click",function(){e.classList.toggle("active"),this.classList.toggle("active"),document.body.classList.toggle("menu-open")}),document.addEventListener("click",function(n){e.contains(n.target)||t.contains(n.target)||(e.classList.remove("active"),t.classList.remove("active"),document.body.classList.remove("menu-open"))}))}function initLazyLoading(){if("IntersectionObserver"in window){const t=document.querySelectorAll('img[data-src], img[loading="lazy"]'),e=new IntersectionObserver((t,e)=>{t.forEach(t=>{if(t.isIntersecting){const n=t.target;n.dataset.src&&(n.src=n.dataset.src,n.removeAttribute("data-src")),n.classList.add("loaded"),e.unobserve(n)}})});t.forEach(t=>e.observe(t))}}function initScrollAnimations(){if("IntersectionObserver"in window){const t=document.querySelectorAll(".animate-on-scroll"),e=new IntersectionObserver(t=>{t.forEach(t=>{t.isIntersecting&&(t.target.classList.add("animated"),e.unobserve(t.target))})},{threshold:.1,rootMargin:"0px 0px -50px 0px"});t.forEach(t=>e.observe(t))}}document.addEventListener("DOMContentLoaded",function(){console.log("Quindío Travel - Main JavaScript loaded"),initSmoothScrolling(),initMobileMenu(),initLazyLoading(),initScrollAnimations()});const Utils={debounce(t,e){let n;return function(...o){clearTimeout(n),n=setTimeout(()=>{clearTimeout(n),t(...o)},e)}},throttle(t,e){let n;return function(...o){n||(t.apply(this,o),n=!0,setTimeout(()=>n=!1,e))}},formatCurrency:(t,e="es-CO",n="COP")=>new Intl.NumberFormat(e,{style:"currency",currency:n,minimumFractionDigits:0,maximumFractionDigits:0}).format(t)};window.QuindioTravelUtils=Utils;